/* Translate a key. Falls back to English, then to the key itself. */
function t(key, vars) {
  const lang = (typeof settings !== "undefined" && settings.lang) || "en";
  const L = STRINGS[lang] || STRINGS.en;
  let s = L[key] !== undefined ? L[key] : (STRINGS.en[key] !== undefined ? STRINGS.en[key] : key);
  if (vars) Object.keys(vars).forEach(k => { s = String(s).split("{" + k + "}").join(vars[k]); });
  return s;
}

/* Walk the static DOM and translate everything tagged with data-i18n*. */
function applyI18n() {
  document.querySelectorAll("[data-i18n]").forEach(el => { el.textContent = t(el.dataset.i18n); });
  document.querySelectorAll("[data-i18n-html]").forEach(el => { el.innerHTML = t(el.dataset.i18nHtml); });
  document.querySelectorAll("[data-i18n-ph]").forEach(el => { el.placeholder = t(el.dataset.i18nPh); });
  document.documentElement.lang = (typeof settings !== "undefined" && settings.lang === "my") ? "my" : ((typeof settings !== "undefined" && settings.lang) || "en");
}



